(* emoji_gen — build-time generator for the native emoji table.

   Reads resources/js/emoji-data.js (itself generated by
   scripts/gen-emoji-data.mjs from @emoji-mart/data's native set) and
   emits apple/emoji_mart_data.ml: the (id, display name, native char,
   search keywords) table apple/emoji_mart.ml consumes. Keeping the
   dataset generated means emoji-mart upgrades flow through
   emoji-data.js without a stale committed copy. *)

let die fmt = Printf.ksprintf (fun s -> prerr_endline s; exit 1) fmt

(* OCaml string literal quoting that keeps UTF-8 bytes raw (only
   dquote/backslash/control chars need escaping) — %S would
   decimal-escape emoji *)
let lit s =
  let b = Buffer.create (String.length s + 2) in
  Buffer.add_char b '"';
  String.iter
    (fun c ->
      match c with
      | '"' -> Buffer.add_string b "\\\""
      | '\\' -> Buffer.add_string b "\\\\"
      | '\n' -> Buffer.add_string b "\\n"
      | '\t' -> Buffer.add_string b "\\t"
      | '\r' -> Buffer.add_string b "\\r"
      | c when c < ' ' || c = '\x7f' -> Printf.bprintf b "\\%03d" (Char.code c)
      | c -> Buffer.add_char b c)
    s;
  Buffer.add_char b '"';
  Buffer.contents b

let () =
  match Sys.argv with
  | [| _; emoji_js_path; out_path |] ->
      let ic = open_in_bin emoji_js_path in
      let raw = really_input_string ic (in_channel_length ic) in
      close_in ic;
      (* strip the `globalThis.__emojiData=` assignment prefix and any
         trailing `;` — the payload is plain JSON *)
      let json_text =
        match
          (String.index_opt raw '{', String.rindex_opt raw '}')
        with
        | Some i, Some j when j > i -> String.sub raw i (j - i + 1)
        | _ -> die "emoji_gen: no JSON object in %s" emoji_js_path
      in
      let json =
        try Yojson.Safe.from_string json_text
        with e -> die "emoji_gen: %s: %s" emoji_js_path (Printexc.to_string e)
      in
      let emojis =
        match Yojson.Safe.Util.member "emojis" json with
        | `Assoc xs -> xs
        | _ -> die "emoji_gen: .emojis is not an object"
      in
      let oc = open_out_bin out_path in
      Printf.fprintf oc
        "(* generated by tools/emoji_gen.exe from resources/js/emoji-data.js — \
         do not edit *)\n\n\
         let table : (string * string * string * string) array = [|\n";
      List.iter
        (fun (id, v) ->
          let open Yojson.Safe.Util in
          let name = v |> member "name" |> to_string in
          let keywords =
            v |> member "keywords" |> to_list |> List.map to_string
            |> String.concat " "
          in
          let native =
            match v |> member "skins" |> to_list with
            | `Assoc skin :: _ -> (
                match List.assoc_opt "native" skin with
                | Some (`String ch) -> ch
                | _ -> die "emoji_gen: %s has no native skin" id)
            | _ -> die "emoji_gen: %s has no skins" id
          in
          Printf.fprintf oc "  (%s, %s, %s, %s);\n" (lit id) (lit name)
            (lit native) (lit keywords))
        emojis;
      Printf.fprintf oc "|]\n";
      close_out oc
  | _ -> die "usage: emoji_gen <emoji-data.js> <out.ml>"
